export function sourceLanguage(text){if(/[\u3040-\u30ff]/u.test(text))return'ja';if(/[\uac00-\ud7af]/u.test(text))return'ko';if(/[\u4e00-\u9fff]/u.test(text))return'zh-CN';if(/[\u0400-\u04ff]/u.test(text))return'ru';if(/[\u0600-\u06ff]/u.test(text)&&!/[A-Za-z]{12}/u.test(text))return'ar';return'en'}
export function byteChunks(text,max=450){const chunks=[];let current='';const enc=new TextEncoder();for(const c of text){if(enc.encode(current+c).length>max){if(current)chunks.push(current);current=c}else current+=c}if(current)chunks.push(current);return chunks;}
export function arabicLanguage(lang){return({JavaScript:'جافاسكربت',TypeScript:'تايب سكربت',Python:'بايثون',Rust:'رست',Go:'جو',Java:'جافا',Kotlin:'كوتلن',Dart:'دارت',Swift:'سويفت',Shell:'أوامر النظام',HTML:'لغة صفحات الويب',CSS:'تنسيق الويب',C:'سي','C++':'سي بلس بلس','C#':'سي شارب',PHP:'بي إتش بي',Ruby:'روبي',Vue:'فيو',JupyterNotebook:'دفاتر برمجية','Jupyter Notebook':'دفاتر برمجية',Markdown:'مستندات نصية',PowerShell:'باور شل',Dockerfile:'إعداد الحاويات',CMake:'إعداد البناء',R:'آر',Scala:'سكالا',Elixir:'إليكسير',Lua:'لوا',Haskell:'هاسكل',Svelte:'سفلت',Clojure:'كلوجر',ObjectiveC:'أوبجكتف سي','Objective-C':'أوبجكتف سي',TeX:'تنضيد المستندات',VimScript:'إعداد المحرر',Vim:'إعداد المحرر',Nix:'نيكس',Assembly:'أسمبلي'})[lang]||'لغة تقنية أخرى'}
export function plainReadme(text){return text.replace(/```[\s\S]*?```/g,'\n').replace(/~~~[\s\S]*?~~~/g,'\n').replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/<[^>]*>/g,'').replace(/https?:\/\/\S+/g,'').replace(/^[#>*|\s-]+/gm,'').replace(/\n{3,}/g,'\n\n').trim();}
export function safePublicURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null}catch{return null}}
export function safeAssetURL(value,fullName){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='github.com'&&u.pathname.startsWith('/'+fullName+'/releases/download/')?u.href:null}catch{return null}}
export function createTranslator({fetcher=globalThis.fetch,storage,clock=()=>Date.now()}={}){if(storage===undefined){try{storage=globalThis.localStorage}catch{}}const inFlight=new Map();let quotaBlocked=false;const queue=[];let active=0;const cacheKey='radar-ar-v1';let cache={};try{cache=JSON.parse(storage?.getItem(cacheKey)||'{}')}catch{}if(!cache||typeof cache!=='object')cache={};
function schedule(fn){return new Promise((resolve,reject)=>{queue.push({fn,resolve,reject});pump()})}function pump(){if(active>=2||!queue.length)return;const job=queue.shift();active++;Promise.resolve().then(job.fn).then(job.resolve,job.reject).finally(()=>{active--;pump()})}
function saved(k){const v=cache[k];return v&&typeof v.ar==='string'&&v.at>clock()-30*86400000?v.ar:null}
async function translate(text,language=sourceLanguage(text)){text=String(text||'').trim();if(!text)return'';if(language==='ar')return text;const key=language+'|'+text;const hit=saved(key);if(hit)return hit;if(inFlight.has(key))return inFlight.get(key);const task=schedule(async()=>{if(quotaBlocked)throw new Error('وصلت خدمة الترجمة لحد الاستخدام. النصوص المترجمة سابقًا متاحة.');let parts=[];for(const part of byteChunks(text)){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),14000);try{const url=new URL('https://api.mymemory.translated.net/get');url.search=new URLSearchParams({q:part,langpair:language+'|ar'});const response=await fetcher(url,{signal:controller.signal});if(!response.ok)throw new Error('خدمة الترجمة غير متاحة الآن.');const data=await response.json();if(data.quotaFinished||Number(data.responseStatus)===429){quotaBlocked=true;throw new Error('وصلت خدمة الترجمة لحد الاستخدام. أعد المحاولة لاحقًا.')}if(Number(data.responseStatus)!==200||!data.responseData?.translatedText)throw new Error('لم تتوفر ترجمة عربية موثوقة لهذا النص.');const value=data.responseData.translatedText;if(/MYMEMORY WARNING|QUERY LENGTH LIMIT|INVALID SOURCE|SELECT TWO DISTINCT/i.test(value))throw new Error('تعذر ترجمة النص. جرّب تحديد اللغة من صفحة التفاصيل.');parts.push(value)}catch(error){if(error.name==='AbortError')throw new Error('تأخرت خدمة الترجمة. جرّب مجددًا.');throw error}finally{clearTimeout(timer)}}const result=parts.join(' ');if(!/[\u0600-\u06ff]/u.test(result))throw new Error('النتيجة لا تحتوي على شرح عربي. جرّب لغة المصدر المناسبة.');cache[key]={ar:result,at:clock()};const entries=Object.entries(cache);if(entries.length>300)cache=Object.fromEntries(entries.slice(-300));try{storage?.setItem(cacheKey,JSON.stringify(cache))}catch{}return result;});inFlight.set(key,task);try{return await task}finally{inFlight.delete(key)}}
return{translate,peek:(text,language=sourceLanguage(text))=>saved(language+'|'+String(text||'').trim()),resetQuota:()=>{quotaBlocked=false}};}
